// OneSignal & Web Push Service Worker + PWA Offline Support (v10 - Colored Emblem Notification Shade)
const CACHE_NAME = "three-youths-pwa-v10";
const COLOR_BADGE_PATH = "/notif-logo-color.png?v=10";
const EMPTY_ICON_PATH = "/notif-empty.png?v=10";

// Pre-embedded 128x128 Full-Color Emblem WITHOUT text underneath (transparent exterior)
const COLOR_EMBLEM_RAW_B64 = "";
// Pre-embedded 32x32 100% Transparent PNG to hide right-side bell icon
const EMPTY_RAW_B64 = "iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAGklEQVR42u3BAQEAAACCIP+vbkhAAQAAAO8GECAAAcm1w7EAAAAASUVORK5CYII=";

function base64ToUint8Array(b64) {
  const clean = String(b64 || "").replace(/^data:[^;]+;base64,/, "").trim();
  const binary = atob(clean);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

const COLOR_EMBLEM_BYTES = base64ToUint8Array(COLOR_EMBLEM_RAW_B64);
const EMPTY_ICON_BYTES = base64ToUint8Array(EMPTY_RAW_B64);

const PRECACHE_ASSETS = [
  "/",
  "/index.html",
  "/manifest.json?v=10",
  "/site-logo-with-text.png?v=10",
  "/site-logo-192.png?v=10",
  "/site-logo-512.png?v=10",
  "/site-logo-maskable.png?v=10",
  "/notif-logo-color.png?v=10",
  "/notif-empty.png?v=10"
];

// Intercept showNotification so every notification uses the Colored Emblem on the left and hides the Bell on the right
if (self.ServiceWorkerRegistration && self.ServiceWorkerRegistration.prototype.showNotification) {
  const origShowNotification = self.ServiceWorkerRegistration.prototype.showNotification;
  self.ServiceWorkerRegistration.prototype.showNotification = function(title, options = {}) {
    const cleanTitle = title || "الثلاثة فتية - اجتماع الشباب السوداني";
    const patchedOptions = Object.assign({}, options, {
      badge: COLOR_BADGE_PATH,
      icon: EMPTY_ICON_PATH,
      dir: "rtl",
      lang: "ar",
      vibrate: options.vibrate || [200, 100, 200],
      requireInteraction: options.requireInteraction !== undefined ? options.requireInteraction : true,
      data: Object.assign({}, options.data || {}, {
        url: (options.data && options.data.url) || "/?tab=announcements"
      })
    });
    return origShowNotification.call(this, cleanTitle, patchedOptions);
  };
}

// Handle incoming Web Push events (works even when app & browser are 100% closed)
self.addEventListener("push", function(event) {
  let payload = {};
  if (event.data) {
    try {
      payload = event.data.json();
    } catch (e) {
      try {
        payload = { body: event.data.text() };
      } catch (err) {
        payload = {};
      }
    }
  }

  // Ignore duplicate OneSignal raw payload if OneSignal SDK handles it, or render directly with our patched showNotification
  const custom = payload.custom || {};
  const addData = custom.a || payload.data || {};
  const title = payload.title || payload.heading || "الثلاثة فتية - اجتماع الشباب السوداني";
  const body = payload.body || payload.alert || payload.message || "";
  const targetUrl = payload.url || custom.u || addData.url || "/?tab=announcements";
  const tag = payload.tag || addData.tag || "three-youths-" + Date.now();

  if (!body && !payload.title && !payload.alert) return;

  event.stopImmediatePropagation();
  event.waitUntil(
    self.registration.showNotification(title, {
      body: body,
      badge: COLOR_BADGE_PATH,
      icon: EMPTY_ICON_PATH,
      tag: tag,
      renotify: true,
      requireInteraction: true,
      dir: "rtl",
      lang: "ar",
      vibrate: [250, 120, 250],
      data: Object.assign({}, addData, { url: targetUrl })
    })
  );
}, true);

// Handle notification click to open the app directly on the announcements board
self.addEventListener("notificationclick", function(event) {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "/?tab=announcements";

  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then(function(clientList) {
      for (let i = 0; i < clientList.length; i++) {
        const client = clientList[i];
        if ("focus" in client) {
          client.postMessage({ type: "NOTIFICATION_CLICK", url: targetUrl });
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});

self.addEventListener("install", function(event) {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then(function(cache) {
      cache.put(
        new Request(COLOR_BADGE_PATH),
        new Response(COLOR_EMBLEM_BYTES.slice(0), {
          status: 200,
          headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=31536000" }
        })
      );
      cache.put(
        new Request(EMPTY_ICON_PATH),
        new Response(EMPTY_ICON_BYTES.slice(0), {
          status: 200,
          headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=31536000" }
        })
      );
      return cache.addAll(PRECACHE_ASSETS).catch(function() {});
    })
  );
});

self.addEventListener("activate", function(event) {
  event.waitUntil(
    caches.keys().then(function(keys) {
      return Promise.all(
        keys.map(function(key) {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    }).then(function() {
      return self.clients.claim();
    })
  );
});

self.addEventListener("fetch", function(event) {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);

  // Instant 0ms in-memory response for notification shade emblem and empty right-side icon
  if (
    url.pathname === "/notif-logo-color.png" ||
    url.pathname === "/notif-logo-emblem.png" ||
    url.pathname === "/site-badge.png"
  ) {
    event.respondWith(
      new Response(COLOR_EMBLEM_BYTES.slice(0), {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=31536000, immutable"
        }
      })
    );
    return;
  }

  if (url.pathname === "/notif-empty.png") {
    event.respondWith(
      new Response(EMPTY_ICON_BYTES.slice(0), {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=31536000, immutable"
        }
      })
    );
    return;
  }

  if (url.pathname.startsWith("/api/")) return;

  if (event.request.mode === "navigate") {
    event.respondWith(
      fetch(event.request).catch(function() {
        return caches.match("/index.html");
      })
    );
  }
});

// Load OneSignal SDK Worker after our push and showNotification interceptors
try {
  importScripts("https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.sw.js");
} catch (e) {}
